    c = d.get("cost")
    return c if c is not None else 1e9


def _tree_cost(paths, h):
    """Cost of union of edges across all paths (edge reuse = free)."""
    used, total = set(), 0.0
    for p in paths:
        for i in range(len(p) - 1):
            e = (p[i], p[i + 1])
            if e not in used:
                used.add(e)
                total += _w(e[0], e[1], h[e[0]][e[1]])
    return total


def search_algorithm(src, dsts, G, num_partitions):
    """Shared-trunk broadcast: greedy marginal-cost Steiner tree vs shortest paths.

    Broadcast the same data to many destinations by building a shared delivery
    trunk: once an edge is used by any destination's path, other destinations
    traverse it for free. For each destination (ordered by shortest-path cost,
    plus a few randomized orderings), enumerate candidate simple paths and pick
    the one minimizing the cost of *new* edges only. Compare against plain
    per-destination shortest paths and emit whichever yields the cheaper
    edge union, so the result is never worse than either strategy alone.
    """
